#!/usr/bin/env node
// electron/src/rt/electron-plugins.js is regenerated by every
// `cap sync @capacitor-community/electron` — it's a flat
// `const X = require('.../electron/dist/plugin.js'); module.exports = {X}`.
// Some plugins' Electron bundles (e.g. @capacitor-community/sqlite@8.x,
// built with Rollup) wrap their real export in a `.default` layer instead
// of exporting the plugin class flatly. Both halves of
// @capacitor-community/electron's plugin loader — the main-process
// setupCapacitorElectronPlugins() and the renderer's electron-rt.ts — do
// `Object.keys(pluginModule).filter(k => k !== 'default')` to find plugin
// classes, so a `.default`-wrapped module silently yields zero classes and
// zero registered methods, with no error anywhere. Since that loader code
// lives in node_modules (can't be hand-patched durably) and this file gets
// regenerated on every sync (same problem), the one place a fix survives
// is right here, run right after sync and before anything else requires it.
const fs = require('fs');
const path = require('path');

const file = path.join(__dirname, '..', 'src', 'rt', 'electron-plugins.js');
if (!fs.existsSync(file)) {
  process.exit(0);
}

const src = fs.readFileSync(file, 'utf8');
const patched = `${src}
// --- SmartChef fix: unwrap Rollup's \`.default\` CJS-interop wrapper -------
// See comment in electron/scripts/fix-electron-plugins.js for why this is
// here instead of upstream. Idempotent: once unwrapped, a plugin's export
// no longer has a lone 'default' key, so re-running this is a no-op.
for (const key of Object.keys(module.exports)) {
  const mod = module.exports[key];
  if (mod && typeof mod === 'object' && 'default' in mod && Object.keys(mod).length === 1) {
    module.exports[key] = mod.default;
  }
}
`;

fs.writeFileSync(file, patched);
console.log('[fix-electron-plugins] normalized default-wrapped plugin exports');
